n_bits = 0:numel(nrz_values)-1;
n_sym = 0:numel(qam_symbols)-1;
n_interp = 0:numel(interp_out)-1;
t_interp = n_interp / hw_sps;
n_diag4 = 0:numel(diagnostic4_out)-1;
t_diag4 = n_diag4 / plot_sps;
n_tx = 0:numel(tx_out)-1;

figure('Name', ['TX chain overview, ', mode]);
tiledlayout(5, 1);
nexttile; stairs(n_bits, nrz_values, 'LineWidth', 1); grid on;
ylim([-1.25 1.25]); xlabel('bit index'); ylabel('NRZ'); title('Input NRZ bit stream');
nexttile; stem(n_sym, real(qam_symbols), '.-'); hold on; stem(n_sym, imag(qam_symbols), '.-'); hold off; grid on;
xlabel('symbol index'); ylabel('amplitude'); legend('I', 'Q'); title('Mapped symbols');
nexttile; plot(t_interp, real(interp_out), '.-', t_interp, imag(interp_out), '.-'); grid on;
xlabel('symbol index'); ylabel('amplitude'); legend('I', 'Q'); title(['Hardware ', interp_mode, ' pulse-shaped baseband output']);
nexttile; plot(t_diag4, real(diagnostic4_out), '-', t_diag4, imag(diagnostic4_out), '-'); grid on;
xlabel('symbol index'); ylabel('amplitude'); legend('I', 'Q'); title('Diagnostic 4-sps RRC output, span=8, beta=0.35');
nexttile; plot(n_tx, real(tx_out), '.-', n_tx, imag(tx_out), '.-'); grid on;
xlabel('sample index'); ylabel('amplitude'); legend('I', 'Q'); title('Mixed TX output');

figure('Name', ['Constellation, ', mode]);
subplot(1, 2, 1); plot(real(qam_symbols), imag(qam_symbols), 'o'); grid on; axis equal;
xlabel('I'); ylabel('Q'); title('Symbol constellation');
subplot(1, 2, 2); plot(real(interp_out), imag(interp_out), '.-'); grid on; axis equal;
xlabel('I'); ylabel('Q'); title('Pulse-shaped trajectory');

figure('Name', ['Pulse-shaping comparison, ', mode]);
subplot(2, 1, 1); plot(t_interp, real(interp_out), '.-', t_interp, imag(interp_out), '.-'); grid on;
legend('I', 'Q'); xlabel('symbol index'); ylabel('amplitude'); title(['Hardware ', interp_mode, ' output samples']);
subplot(2, 1, 2); plot(t_diag4, real(diagnostic4_out), t_diag4, imag(diagnostic4_out)); grid on;
legend('I', 'Q'); xlabel('symbol index'); ylabel('amplitude'); title('4-sps scalar RRC reference');

figure('Name', ['Final TX IQ, ', mode]);
subplot(2, 1, 1); plot(n_tx, real(tx_out), '.-', n_tx, imag(tx_out), '.-'); grid on;
legend('real', 'imag'); title(['TX chain output, ', mode]); xlabel('sample index');
subplot(2, 1, 2); plot(real(tx_out), imag(tx_out), '.-'); grid on;
axis equal; xlabel('I'); ylabel('Q'); title('Mixed output IQ trajectory');
